INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0a0c10\">\n<title>KubeDock</title>\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Ccircle cx='16' cy='16' r='15' fill='%230a0c10' stroke='%235ce1c6' stroke-width='1.4'/%3E%3Cg stroke='%235ce1c6' stroke-width='1.6' stroke-linecap='round'%3E%3Ccircle cx='16' cy='16' r='4.2' fill='none'/%3E%3Cline x1='16' y1='4.5' x2='16' y2='9.5'/%3E%3Cline x1='16' y1='22.5' x2='16' y2='27.5'/%3E%3Cline x1='4.5' y1='16' x2='9.5' y2='16'/%3E%3Cline x1='22.5' y1='16' x2='27.5' y2='16'/%3E%3Cline x1='7.8' y1='7.8' x2='11.1' y2='11.1'/%3E%3Cline x1='20.9' y1='20.9' x2='24.2' y2='24.2'/%3E%3Cline x1='24.2' y1='7.8' x2='20.9' y2='11.1'/%3E%3Cline x1='11.1' y1='20.9' x2='7.8' y2='24.2'/%3E%3C/g%3E%3C/svg%3E\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\n<style>\n  :root {\n    /* -- color -- */\n    --bg:         #0a0c10;\n    --bg-panel:   #12151c;\n    --bg-elevated:#171b24;\n    --bg-hover:   #1d222c;\n    --border:     #232838;\n    --border-soft:#1a1e29;\n    --text:       #eef0f4;\n    --text-dim:   #9aa1b0;\n    --text-faint: #5b6172;\n    --accent:     #5ce1c6;\n    --accent-dim: rgba(92,225,198,0.14);\n    --ok:         #3ecf8e;\n    --warn:       #f2b84b;\n    --err:        #f2506d;\n    --muted:      #6b7284;\n  }\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body {\n    margin: 0; padding: 0; height: 100%;\n    background: var(--bg); color: var(--text);\n    font-family: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n    font-size: 15px;\n    -webkit-font-smoothing: antialiased;\n  }\n  ::selection { background: var(--accent-dim); color: var(--text); }\n  :focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 4px; }\n\n  #app { display: flex; flex-direction: column; height: 100vh; height: 100dvh; }\n  body.app-locked #app { visibility:hidden; }\n  #login-gate { display:none; }\n  #login-gate.open { display:flex; }\n  #login-panel { width:min(380px,100%); background:var(--bg-panel); border:1px solid var(--border); border-radius:12px; padding:24px; text-align:left; box-shadow:0 18px 50px rgba(0,0,0,.35); }\n  #login-panel h2 { margin:0 0 8px; font-size:18px; }\n  #login-panel p { color:var(--text-dim); font-size:13px; line-height:1.5; }\n  #login-panel label { display:block; margin:16px 0 6px; font-size:12px; color:var(--text-dim); }\n  #login-code { width:100%; background:var(--bg); border:1px solid var(--border); border-radius:7px; padding:12px; color:var(--text); font:20px 'IBM Plex Mono',monospace; letter-spacing:5px; text-align:center; }\n  #login-submit, #logout-btn { background:var(--accent-dim); border:1px solid rgba(92,225,198,.35); color:var(--accent); border-radius:7px; padding:10px 14px; font-weight:600; }\n  #login-submit { width:100%; margin-top:14px; }\n  #login-submit:disabled { opacity:.5; }\n  #login-error { min-height:18px; color:var(--err)!important; }\n  #logout-btn { font-size:12px; padding:6px 9px; margin-left:8px; }\n\n  /* ---------- header ---------- */\n  header {\n    display: flex; align-items: center; justify-content: space-between;\n    padding: 14px 16px 12px;\n    padding-top: calc(14px + env(safe-area-inset-top, 0px));\n    background: var(--bg-panel); border-bottom: 1px solid var(--border-soft);\n  }\n  header h1 {\n    font-size: 16px; margin: 0; display: flex; align-items: baseline; gap: 8px;\n    font-weight: 600; letter-spacing: 0.01em;\n  }\n  header h1 .glyph {\n    color: var(--accent); font-size: 17px; line-height: 1;\n    font-family: 'IBM Plex Mono', monospace;\n  }\n  .ns-picker { display: flex; align-items: center; gap: 2px; }\n  .ns-picker::before {\n    content: \"ns:\"; color: var(--text-faint); font-family: 'IBM Plex Mono', monospace;\n    font-size: 12px; margin-right: 2px;\n  }\n  header .ns-select {\n    background: none; color: var(--accent); border: none;\n    font-family: 'IBM Plex Mono', monospace;\n    font-size: 12.5px; padding: 4px 4px; max-width: 30vw;\n  }\n  #refresh-btn {\n    background: none; border: none; color: var(--text-dim); font-size: 17px;\n    padding: 4px 6px 4px 10px; line-height: 1;\n  }\n  #refresh-btn.spinning { animation: spin 0.7s linear infinite; }\n  @keyframes spin { to { transform: rotate(360deg); } }\n  @media (prefers-reduced-motion: reduce) {\n    #refresh-btn.spinning { animation: none; }\n  }\n\n  /* ---------- tabs ---------- */\n  nav {\n    display: flex; background: var(--bg-panel); border-bottom: 1px solid var(--border);\n    overflow-x: auto; padding: 0 8px;\n  }\n  nav::-webkit-scrollbar { display: none; }\n  nav button {\n    flex: 1; background: none; border: none; color: var(--text-dim);\n    padding: 11px 10px 10px; font-size: 13px; font-weight: 500;\n    border-bottom: 2px solid transparent; white-space: nowrap;\n  }\n  nav button.active { color: var(--text); border-bottom-color: var(--accent); }\n\n  /* ---------- search ---------- */\n  #search-bar {\n    display: flex; align-items: center; gap: 8px;\n    background: var(--bg-panel); border-bottom: 1px solid var(--border);\n    padding: 9px 14px;\n  }\n  #search-bar .glyph {\n    color: var(--text-faint); font-size: 13px; font-family: 'IBM Plex Mono', monospace; flex: none;\n  }\n  #search-input {\n    flex: 1; background: none; border: none; color: var(--text);\n    font-family: 'IBM Plex Mono', monospace; font-size: 13px; min-width: 0;\n  }\n  #search-input::placeholder { color: var(--text-faint); }\n  #search-clear {\n    background: none; border: none; color: var(--text-faint); font-size: 15px;\n    padding: 2px 4px; display: none; line-height: 1;\n  }\n  #search-clear.show { display: block; }\n  #search-count {\n    color: var(--text-faint); font-size: 11.5px; font-family: 'IBM Plex Mono', monospace; flex: none;\n  }\n\n  main { flex: 1; overflow-y: auto; padding: 0 0 calc(24px + env(safe-area-inset-bottom, 0px)); }\n\n  /* ---------- rows ---------- */\n  .card {\n    background: var(--bg-panel);\n    border-bottom: 1px solid var(--border-soft);\n    border-left: 3px solid var(--border);\n    padding: 13px 16px 13px 13px;\n  }\n  .card.status-ok    { border-left-color: var(--ok); }\n  .card.status-warn  { border-left-color: var(--warn); }\n  .card.status-err   { border-left-color: var(--err); }\n  .card.status-muted { border-left-color: var(--muted); }\n\n  .card-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }\n  .card-title {\n    font-weight: 500; font-size: 14px; word-break: break-all;\n    font-family: 'IBM Plex Mono', monospace;\n  }\n  .card-sub { color: var(--text-faint); font-size: 12px; margin-top: 3px; }\n\n  .badge {\n    font-size: 12px; font-weight: 500; white-space: nowrap;\n    display: flex; align-items: center; gap: 5px; padding-top: 1px;\n  }\n  .badge::before {\n    content: \"\"; width: 6px; height: 6px; border-radius: 50%; flex: none;\n    background: currentColor;\n  }\n  .badge.ok    { color: var(--ok); }\n  .badge.warn  { color: var(--warn); }\n  .badge.err   { color: var(--err); }\n  .badge.muted { color: var(--muted); }\n\n  .card-meta {\n    display: flex; flex-wrap: wrap; gap: 12px; margin-top: 9px;\n    font-size: 12px; color: var(--text-dim); font-family: 'IBM Plex Mono', monospace;\n  }\n  .card-meta span b { color: var(--text); font-weight: 500; }\n\n  .card-actions { display: flex; gap: 8px; margin-top: 11px; }\n  .card-actions button {\n    flex: 1; background: var(--bg-elevated); color: var(--text-dim); border: 1px solid var(--border);\n    border-radius: 6px; padding: 8px; font-size: 12.5px; font-weight: 500;\n  }\n  .card-actions button:active { background: var(--bg-hover); }\n  .card-actions button.danger { color: var(--err); border-color: rgba(242,80,109,0.3); }\n  .card-actions button.accent { color: var(--accent); border-color: rgba(92,225,198,0.3); }\n\n  .empty, .loading, .error {\n    text-align: center; color: var(--text-faint); padding: 60px 24px; font-size: 13.5px;\n    font-family: 'IBM Plex Mono', monospace;\n  }\n  .error { color: var(--err); }\n\n  mark {\n    background: var(--accent-dim); color: var(--accent); border-radius: 2px;\n    padding: 0 1px; font-weight: 500;\n  }\n\n  /* ---------- log / detail sheet ---------- */\n  #modal-backdrop {\n    position: fixed; inset: 0; background: rgba(5,6,9,0.65); z-index: 50;\n    display: none; align-items: flex-end;\n  }\n  #modal-backdrop.open { display: flex; }\n  #modal {\n    background: var(--bg-panel); width: 100%; max-height: 82vh;\n    border-radius: 14px 14px 0 0; display: flex; flex-direction: column;\n    border-top: 1px solid var(--border);\n  }\n  #modal-header {\n    display: flex; justify-content: space-between; align-items: center;\n    padding: 14px 16px; border-bottom: 1px solid var(--border-soft);\n  }\n  #modal-header h2 {\n    font-size: 13.5px; margin: 0; word-break: break-all; padding-right: 10px;\n    font-family: 'IBM Plex Mono', monospace; font-weight: 500; color: var(--text-dim);\n  }\n  #modal-close { background: none; border: none; color: var(--text-dim); font-size: 19px; padding: 2px 4px; }\n  #modal-body {\n    padding: 14px 16px calc(18px + env(safe-area-inset-bottom, 0px));\n    overflow-y: auto; font-family: 'IBM Plex Mono', ui-monospace, monospace;\n    font-size: 12px; line-height: 1.6; white-space: pre-wrap; word-break: break-word; color: var(--text-dim);\n    background: var(--bg);\n  }\n\n  #toast {\n    position: fixed; left: 50%; bottom: calc(24px + env(safe-area-inset-bottom, 0px));\n    transform: translateX(-50%) translateY(20px); background: var(--bg-elevated);\n    border: 1px solid var(--border); color: var(--text); padding: 10px 16px;\n    border-radius: 8px; font-size: 13px; opacity: 0; transition: all 0.2s ease;\n    z-index: 60; max-width: 90%; text-align: center;\n    font-family: 'IBM Plex Mono', monospace;\n  }\n  #toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n\n  #login-gate {\n    position: fixed; inset: 0; background: var(--bg); z-index: 100;\n    display: flex; align-items: center; justify-content: center; text-align: center;\n    padding: 20px; color: var(--text-dim); font-size: 13.5px;\n    font-family: 'IBM Plex Mono', monospace;\n  }\n</style>\n</head>\n<body class=\"app-locked\">\n<div id=\"app\">\n  <header>\n    <h1><span class=\"glyph\">⎈</span>KubeDock</h1>\n    <div style=\"display:flex; align-items:center;\">\n      <div class=\"ns-picker\">\n        <select id=\"ns-select\" class=\"ns-select\"><option value=\"all\">all</option></select>\n      </div>\n      <button id=\"refresh-btn\" title=\"Refresh\">⟳</button>\n      <button id=\"logout-btn\" title=\"Sign out\">Sign out</button>\n    </div>\n  </header>\n\n  <nav id=\"tabs\">\n    <button data-tab=\"pods\" class=\"active\">Pods</button>\n    <button data-tab=\"deployments\">Deployments</button>\n    <button data-tab=\"services\">Services</button>\n    <button data-tab=\"nodes\">Nodes</button>\n    <button data-tab=\"events\">Events</button>\n  </nav>\n\n  <div id=\"search-bar\">\n    <span class=\"glyph\">/</span>\n    <input id=\"search-input\" type=\"text\" placeholder=\"filter pods by name…\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n    <span id=\"search-count\"></span>\n    <button id=\"search-clear\" title=\"Clear\">✕</button>\n  </div>\n\n  <main id=\"content\">\n    <div class=\"loading\">loading…</div>\n  </main>\n</div>\n\n<div id=\"modal-backdrop\">\n  <div id=\"modal\">\n    <div id=\"modal-header\">\n      <h2 id=\"modal-title\"></h2>\n      <button id=\"modal-close\">✕</button>\n    </div>\n    <div id=\"modal-body\"></div>\n  </div>\n</div>\n\n<div id=\"toast\"></div>\n<div id=\"login-gate\" class=\"open\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"login-title\">\n  <form id=\"login-panel\">\n    <h2 id=\"login-title\">Sign in to KubeDock</h2>\n    <p>Enter the current six-digit code from KubeDock → Settings → Web App. Codes rotate every 30 seconds.</p>\n    <label for=\"login-code\">One-time password</label>\n    <input id=\"login-code\" name=\"code\" type=\"text\" inputmode=\"numeric\" autocomplete=\"one-time-code\" pattern=\"[0-9]{6}\" maxlength=\"6\" required aria-describedby=\"login-error\">\n    <p id=\"login-error\" role=\"status\" aria-live=\"polite\"></p>\n    <button id=\"login-submit\" type=\"submit\">Connect</button>\n  </form>\n</div>\n<script>\nconst state = { tab: \"pods\", namespace: \"all\", queries: { pods: \"\", deployments: \"\", services: \"\", nodes: \"\", events: \"\" }, rawData: null };\n\nconst SEARCH_FIELDS = {\n  pods:        p  => p.name,\n  deployments: d  => d.name,\n  services:    s  => s.name,\n  nodes:       n  => n.name,\n  events:      ev => [ev.reason, ev.object, ev.message].filter(Boolean).join(\" \"),\n};\n\nfunction escapeHtml(str) {\n  return str.replace(/[&<>\"']/g, c => ({ \"&\":\"&amp;\", \"<\":\"&lt;\", \">\":\"&gt;\", '\"':\"&quot;\", \"'\":\"&#39;\" }[c]));\n}\n\nfunction filterData(data, tab, query) {\n  if (!query) return data;\n  const q = query.toLowerCase();\n  const getField = SEARCH_FIELDS[tab];\n  return data.filter(item => (getField(item) || \"\").toLowerCase().includes(q));\n}\n\nfunction highlightMatches(query) {\n  const q = query.toLowerCase();\n  document.querySelectorAll(\".card-title\").forEach(node => {\n    const text = node.textContent;\n    const idx = text.toLowerCase().indexOf(q);\n    if (idx === -1) return;\n    const before = escapeHtml(text.slice(0, idx));\n    const match = escapeHtml(text.slice(idx, idx + q.length));\n    const after = escapeHtml(text.slice(idx + q.length));\n    node.innerHTML = before + \"<mark>\" + match + \"</mark>\" + after;\n  });\n}\n\nfunction updateSearchCount(shown, total, query) {\n  const countEl = document.getElementById(\"search-count\");\n  countEl.textContent = query ? (shown + \"/\" + total) : \"\";\n}\n\nfunction renderFiltered() {\n  const cfg = TAB_CONFIG[state.tab];\n  const query = state.queries[state.tab].trim();\n  const data = state.rawData || [];\n  const filtered = filterData(data, state.tab, query);\n  cfg.render(filtered);\n  updateSearchCount(filtered.length, data.length, query);\n  if (query) highlightMatches(query);\n}\n\nfunction toast(msg, isError) {\n  const el = document.getElementById(\"toast\");\n  el.textContent = msg;\n  el.style.color = isError ? \"var(--err)\" : \"var(--text)\";\n  el.classList.add(\"show\");\n  setTimeout(() => el.classList.remove(\"show\"), 2200);\n}\n\nasync function api(path, opts) {\n  const res = await fetch(path, opts);\n  if (res.status === 401) {\n    showLoginGate(\"Session expired. Sign in with a new OTP.\");\n    throw new Error(\"unauthorized\");\n  }\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) {\n    throw new Error(data.detail || (\"Request failed (\" + res.status + \")\"));\n  }\n  return data;\n}\n\nfunction openModal(title, bodyText) {\n  document.getElementById(\"modal-title\").textContent = title;\n  document.getElementById(\"modal-body\").textContent = bodyText;\n  document.getElementById(\"modal-backdrop\").classList.add(\"open\");\n}\ndocument.getElementById(\"modal-close\").onclick = () =>\n  document.getElementById(\"modal-backdrop\").classList.remove(\"open\");\ndocument.getElementById(\"modal-backdrop\").onclick = (e) => {\n  if (e.target.id === \"modal-backdrop\") e.target.classList.remove(\"open\");\n};\n\nfunction el(tag, cls, text) {\n  const e = document.createElement(tag);\n  if (cls) e.className = cls;\n  if (text !== undefined) e.textContent = text;\n  return e;\n}\n\nfunction statusBadge(text, kind) {\n  return el(\"span\", \"badge \" + kind, text);\n}\n\n// ---------- renderers ----------\n\nfunction renderPods(pods) {\n  const content = document.getElementById(\"content\");\n  content.innerHTML = \"\";\n  if (!pods.length) { content.appendChild(el(\"div\", \"empty\", \"No pods in this namespace.\")); return; }\n\n  pods.forEach(p => {\n    let kind = \"muted\";\n    if (p.phase === \"Running\") kind = \"ok\";\n    else if (p.phase === \"Pending\") kind = \"warn\";\n    else if (p.phase === \"Failed\" || p.phase === \"Unknown\") kind = \"err\";\n\n    const card = el(\"div\", \"card status-\" + kind);\n    const top = el(\"div\", \"card-top\");\n    const left = el(\"div\");\n    left.appendChild(el(\"div\", \"card-title\", p.name));\n    left.appendChild(el(\"div\", \"card-sub\", p.namespace + (p.node ? \" · \" + p.node : \"\")));\n    top.appendChild(left);\n    top.appendChild(statusBadge(p.phase || \"?\", kind));\n    card.appendChild(top);\n\n    const meta = el(\"div\", \"card-meta\");\n    meta.appendChild(el(\"span\", null)).innerHTML = \"ready <b>\" + p.ready + \"</b>\";\n    meta.appendChild(el(\"span\", null)).innerHTML = \"restarts <b>\" + p.restarts + \"</b>\";\n    card.appendChild(meta);\n\n    const actions = el(\"div\", \"card-actions\");\n    const logsBtn = el(\"button\", null, \"Logs\");\n    logsBtn.onclick = () => showLogs(p.namespace, p.name, p.containers[0]);\n    actions.appendChild(logsBtn);\n\n    const delBtn = el(\"button\", \"danger\", \"Delete\");\n    delBtn.onclick = () => confirmDeletePod(p.namespace, p.name);\n    actions.appendChild(delBtn);\n    card.appendChild(actions);\n\n    content.appendChild(card);\n  });\n}\n\nfunction renderDeployments(deps) {\n  const content = document.getElementById(\"content\");\n  content.innerHTML = \"\";\n  if (!deps.length) { content.appendChild(el(\"div\", \"empty\", \"No deployments in this namespace.\")); return; }\n\n  deps.forEach(d => {\n    const healthy = d.ready === d.replicas && d.replicas > 0;\n    const kind = healthy ? \"ok\" : \"warn\";\n\n    const card = el(\"div\", \"card status-\" + kind);\n    const top = el(\"div\", \"card-top\");\n    const left = el(\"div\");\n    left.appendChild(el(\"div\", \"card-title\", d.name));\n    left.appendChild(el(\"div\", \"card-sub\", d.namespace));\n    top.appendChild(left);\n    top.appendChild(statusBadge(d.ready + \"/\" + d.replicas, kind));\n    card.appendChild(top);\n\n    const actions = el(\"div\", \"card-actions\");\n    const restartBtn = el(\"button\", \"accent\", \"Restart\");\n    restartBtn.onclick = () => restartDeployment(d.namespace, d.name);\n    actions.appendChild(restartBtn);\n\n    const scaleBtn = el(\"button\", null, \"Scale\");\n    scaleBtn.onclick = () => scaleDeployment(d.namespace, d.name, d.replicas);\n    actions.appendChild(scaleBtn);\n    card.appendChild(actions);\n\n    content.appendChild(card);\n  });\n}\n\nfunction renderServices(services) {\n  const content = document.getElementById(\"content\");\n  content.innerHTML = \"\";\n  if (!services.length) { content.appendChild(el(\"div\", \"empty\", \"No services in this namespace.\")); return; }\n\n  services.forEach(s => {\n    const card = el(\"div\", \"card status-muted\");\n    const top = el(\"div\", \"card-top\");\n    const left = el(\"div\");\n    left.appendChild(el(\"div\", \"card-title\", s.name));\n    left.appendChild(el(\"div\", \"card-sub\", s.namespace + \" · \" + s.clusterIP));\n    top.appendChild(left);\n    top.appendChild(statusBadge(s.type || \"?\", \"muted\"));\n    card.appendChild(top);\n\n    if (s.ports && s.ports.length) {\n      const meta = el(\"div\", \"card-meta\");\n      meta.appendChild(el(\"span\", null, s.ports.join(\", \")));\n      card.appendChild(meta);\n    }\n    content.appendChild(card);\n  });\n}\n\nfunction renderNodes(nodes) {\n  const content = document.getElementById(\"content\");\n  content.innerHTML = \"\";\n  if (!nodes.length) { content.appendChild(el(\"div\", \"empty\", \"No nodes found.\")); return; }\n\n  nodes.forEach(n => {\n    const kind = n.ready ? \"ok\" : \"err\";\n    const card = el(\"div\", \"card status-\" + kind);\n    const top = el(\"div\", \"card-top\");\n    const left = el(\"div\");\n    left.appendChild(el(\"div\", \"card-title\", n.name));\n    left.appendChild(el(\"div\", \"card-sub\", n.version || \"\"));\n    top.appendChild(left);\n    top.appendChild(statusBadge(n.ready ? \"Ready\" : \"Not ready\", kind));\n    card.appendChild(top);\n\n    const meta = el(\"div\", \"card-meta\");\n    meta.appendChild(el(\"span\", null)).innerHTML = \"cpu <b>\" + (n.cpu || \"?\") + \"</b>\";\n    meta.appendChild(el(\"span\", null)).innerHTML = \"mem <b>\" + (n.memory || \"?\") + \"</b>\";\n    card.appendChild(meta);\n\n    content.appendChild(card);\n  });\n}\n\nfunction renderEvents(events) {\n  const content = document.getElementById(\"content\");\n  content.innerHTML = \"\";\n  if (!events.length) { content.appendChild(el(\"div\", \"empty\", \"No recent events.\")); return; }\n\n  events.forEach(ev => {\n    const kind = ev.type === \"Warning\" ? \"warn\" : \"muted\";\n    const card = el(\"div\", \"card status-\" + kind);\n    const top = el(\"div\", \"card-top\");\n    const left = el(\"div\");\n    left.appendChild(el(\"div\", \"card-title\", ev.reason || \"Event\"));\n    left.appendChild(el(\"div\", \"card-sub\", ev.object + \" · \" + (ev.namespace || \"\")));\n    top.appendChild(left);\n    top.appendChild(statusBadge(ev.type || \"?\", kind));\n    card.appendChild(top);\n\n    card.appendChild(el(\"div\", \"card-meta\")).appendChild(el(\"span\", null, ev.message || \"\"));\n    content.appendChild(card);\n  });\n}\n\n// ---------- actions ----------\n\nasync function showLogs(namespace, pod, container) {\n  openModal(pod, \"loading logs…\");\n  try {\n    const q = container ? (\"?container=\" + encodeURIComponent(container)) : \"\";\n    const data = await api(\"/api/logs/\" + encodeURIComponent(namespace) + \"/\" + encodeURIComponent(pod) + q);\n    document.getElementById(\"modal-body\").textContent = data.logs || \"(no output)\";\n  } catch (e) {\n    document.getElementById(\"modal-body\").textContent = \"Error: \" + e.message;\n  }\n}\n\nasync function confirmDeletePod(namespace, name) {\n  if (!confirm(\"Delete pod \\\"\" + name + \"\\\" in \" + namespace + \"?\\nIts controller will usually recreate it.\")) return;\n  try {\n    await api(\"/api/pods/\" + encodeURIComponent(namespace) + \"/\" + encodeURIComponent(name) + \"/delete\", { method: \"POST\" });\n    toast(\"Pod deleted\");\n    loadCurrentTab();\n  } catch (e) { toast(e.message, true); }\n}\n\nasync function restartDeployment(namespace, name) {\n  if (!confirm(\"Rolling-restart \\\"\" + name + \"\\\" in \" + namespace + \"?\")) return;\n  try {\n    await api(\"/api/deployments/\" + encodeURIComponent(namespace) + \"/\" + encodeURIComponent(name) + \"/restart\", { method: \"POST\" });\n    toast(\"Restart triggered\");\n    loadCurrentTab();\n  } catch (e) { toast(e.message, true); }\n}\n\nasync function scaleDeployment(namespace, name, current) {\n  const input = prompt(\"Scale \\\"\" + name + \"\\\" to how many replicas?\", current);\n  if (input === null) return;\n  const replicas = parseInt(input, 10);\n  if (isNaN(replicas) || replicas < 0) { toast(\"Enter a valid replica count\", true); return; }\n  try {\n    await api(\"/api/deployments/\" + encodeURIComponent(namespace) + \"/\" + encodeURIComponent(name) + \"/scale\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ replicas }),\n    });\n    toast(\"Scaled to \" + replicas);\n    loadCurrentTab();\n  } catch (e) { toast(e.message, true); }\n}\n\n// ---------- tab loading ----------\n\nconst TAB_CONFIG = {\n  pods:        { url: \"/api/pods\",        render: renderPods,        nsAware: true },\n  deployments: { url: \"/api/deployments\", render: renderDeployments, nsAware: true },\n  services:    { url: \"/api/services\",    render: renderServices,    nsAware: true },\n  nodes:       { url: \"/api/nodes\",       render: renderNodes,       nsAware: false },\n  events:      { url: \"/api/events\",      render: renderEvents,      nsAware: true },\n};\n\nasync function loadCurrentTab() {\n  const cfg = TAB_CONFIG[state.tab];\n  const btn = document.getElementById(\"refresh-btn\");\n  btn.classList.add(\"spinning\");\n  const content = document.getElementById(\"content\");\n  content.innerHTML = '<div class=\"loading\">loading…</div>';\n  document.getElementById(\"search-count\").textContent = \"\";\n  try {\n    let url = cfg.url;\n    if (cfg.nsAware) url += \"?namespace=\" + encodeURIComponent(state.namespace);\n    const data = await api(url);\n    state.rawData = data;\n    renderFiltered();\n  } catch (e) {\n    state.rawData = null;\n    content.innerHTML = '';\n    content.appendChild(el(\"div\", \"error\", e.message));\n  } finally {\n    btn.classList.remove(\"spinning\");\n  }\n}\n\nasync function loadNamespaces() {\n  try {\n    const namespaces = await api(\"/api/namespaces\");\n    const select = document.getElementById(\"ns-select\");\n    namespaces.forEach(ns => {\n      const opt = document.createElement(\"option\");\n      opt.value = ns; opt.textContent = ns;\n      select.appendChild(opt);\n    });\n  } catch (e) { /* non-fatal — \"all\" still works */ }\n}\n\ndocument.querySelectorAll(\"#tabs button\").forEach(btn => {\n  btn.onclick = () => {\n    document.querySelectorAll(\"#tabs button\").forEach(b => b.classList.remove(\"active\"));\n    btn.classList.add(\"active\");\n    state.tab = btn.dataset.tab;\n    const savedQuery = state.queries[state.tab];\n    document.getElementById(\"search-input\").value = savedQuery;\n    document.getElementById(\"search-input\").placeholder = \"filter \" + btn.dataset.tab + \" by name…\";\n    document.getElementById(\"search-clear\").classList.toggle(\"show\", !!savedQuery);\n    loadCurrentTab();\n  };\n});\n\ndocument.getElementById(\"ns-select\").onchange = (e) => {\n  state.namespace = e.target.value;\n  loadCurrentTab();\n};\n\ndocument.getElementById(\"refresh-btn\").onclick = loadCurrentTab;\n\ndocument.getElementById(\"search-input\").oninput = (e) => {\n  state.queries[state.tab] = e.target.value;\n  document.getElementById(\"search-clear\").classList.toggle(\"show\", !!e.target.value);\n  renderFiltered();\n};\n\ndocument.getElementById(\"search-clear\").onclick = () => {\n  state.queries[state.tab] = \"\";\n  const input = document.getElementById(\"search-input\");\n  input.value = \"\";\n  input.focus();\n  document.getElementById(\"search-clear\").classList.remove(\"show\");\n  renderFiltered();\n};\n\nfunction showLoginGate(message) {\n  document.body.classList.add(\"app-locked\");\n  document.getElementById(\"login-gate\").classList.add(\"open\");\n  document.getElementById(\"login-error\").textContent = message || \"\";\n  document.getElementById(\"login-code\").value = \"\";\n  document.getElementById(\"login-code\").focus();\n}\nfunction hideLoginGate() {\n  document.body.classList.remove(\"app-locked\");\n  document.getElementById(\"login-gate\").classList.remove(\"open\");\n  document.getElementById(\"login-error\").textContent = \"\";\n  loadNamespaces();\n  loadCurrentTab();\n}\nlet loginBusy = false;\ndocument.getElementById(\"login-panel\").addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  if (loginBusy) return;\n  const input = document.getElementById(\"login-code\");\n  const submit = document.getElementById(\"login-submit\");\n  const error = document.getElementById(\"login-error\");\n  const code = input.value.trim();\n  if (!/^\\d{6}$/.test(code)) { error.textContent = \"Enter a six-digit OTP.\"; return; }\n  loginBusy = true;\n  submit.disabled = true;\n  submit.textContent = \"Verifying…\";\n  error.textContent = \"\";\n  try {\n    const response = await fetch(\"/api/login\", {\n      method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n      credentials: \"same-origin\", cache: \"no-store\",\n      body: JSON.stringify({ code }),\n    });\n    const data = await response.json().catch(() => ({}));\n    if (!response.ok) { error.textContent = data.detail || \"OTP authentication failed.\"; input.select(); return; }\n    hideLoginGate();\n  } catch (_) {\n    error.textContent = \"Unable to reach the WebApp. Check the connection and retry.\";\n  } finally {\n    loginBusy = false;\n    submit.disabled = false;\n    submit.textContent = \"Connect\";\n  }\n});\ndocument.getElementById(\"logout-btn\").onclick = async () => {\n  try { await fetch(\"/api/logout\", { method: \"POST\", credentials: \"same-origin\" }); } catch (_) {}\n  state.rawData = null;\n  showLoginGate(\"Signed out. Enter a new OTP to continue.\");\n};\nasync function checkSession() {\n  try {\n    await api(\"/api/session\", { cache: \"no-store\" });\n    document.body.classList.remove(\"app-locked\");\n    document.getElementById(\"login-gate\").classList.remove(\"open\");\n    loadNamespaces();\n    loadCurrentTab();\n  } catch (_) { showLoginGate(\"\"); }\n}\ncheckSession();\n</script>\n</body>\n</html>"
